INSERT INTO LOOKUPMASTER (LOOKUPID,DESCRIPTION,"KEY",TENANT,RECORDSTATUS,"STATEMENT",CONNECTIONNAME,"TYPE",INCLUDEBYROLE,EXCLUDEBYROLE,ISCACHED,STATEMENTTYPE,FIELDS,UPDATEUSERCODE,UPDATEDATE) VALUES (4160,'Póliza de grupos','POLIZA_GRUPO',0,1,'SELECT NUM_POLIZA, NUM_POLIZA ||'' - '' || NOM_POLIZA NOM_POLIZA FROM G2990017 G2917 WHERE G2917.COD_CIA=1 AND G2917.MCA_INH=''N'' ORDER BY G2917.NOM_POLIZA','Tron',2,NULL,NULL,0,1,NULL,1,TIMESTAMP'2025-07-22 00:00:00');
INSERT INTO LOOKUPMASTER (LOOKUPID,DESCRIPTION,"KEY",TENANT,RECORDSTATUS,"STATEMENT",CONNECTIONNAME,"TYPE",INCLUDEBYROLE,EXCLUDEBYROLE,ISCACHED,STATEMENTTYPE,FIELDS,UPDATEUSERCODE,UPDATEDATE) VALUES (4161,'Contratos de una póliza de grupos','CONTRATO_POLIZA_GRUPO',0,1,'SELECT A10.NUM_CONTRATO, A10.NUM_CONTRATO ||'' - '' || G1.NOM_CONTRATO  FROM A2000010 A10 JOIN g2990001 G1 ON G1.COD_CIA =A10.COD_CIA AND G1.NUM_CONTRATO =A10.NUM_CONTRATO  WHERE A10.COD_CIA=1 AND A10.NUM_POLIZA = {num_poliza:varchar}','Tron',2,NULL,NULL,0,1,NULL,1,TIMESTAMP'2025-07-22 00:00:00');
